  1	import java.util.HashMap;
  2	import java.util.Map;
  3	
  4	/**
  5	 * This class collects and provides some statistical data on the state 
  6	 * of a field. It is flexible: it will create and maintain a counter 
  7	 * for any class of object that is found within the field.
  8	 *
  9	 * @version 2016.02.29
 10	 */
 11	public class FieldStats
 12	{
 13	    // Counters for each type of entity (dingo, ant, etc.) in the simulation.
 14	    private Map<Class<?>, Counter> counters;
 15	    // Whether the counters are currently up to date.
 16	    private boolean countsValid;
 17	
 18	    /**
 19	     * Construct a FieldStats object.
 20	     */
 21	    public FieldStats() {
 22	        // Set up a collection for counters for each type of animal that
 23	        // we might find
 24	        counters = new HashMap<>();
 25	        countsValid = true;
 26	    }
 27	
 28	    /**
 29	     * Get details of what is in the field.
 30	     * @return A string describing what is in the field.
 31	     */
 32	    public String getPopulationDetails(Field field) {
 33	        StringBuilder buffer = new StringBuilder();
 34	        if(!countsValid) {
 35	            generateCounts(field);
 36	        }
 37	        for(Counter info : counters.values()) {
 38	            buffer.append(info.getName());
 39	            buffer.append(": ");
 40	            buffer.append(info.getCount());
 41	            buffer.append(' ');
 42	        }
 43	        return buffer.toString();
 44	    }
 45	    
 46	    /**
 47	     * Invalidate the current set of statistics; reset all 
 48	     * counts to zero.
 49	     */
 50	    public void reset() {
 51	        countsValid = false;
 52	        for(Counter count : counters.values()) {
 53	            count.reset();
 54	        }
 55	    }
 56	
 57	    /**
 58	     * Increment the count for one class of animal.
 59	     * @param animalClass The class of animal to increment.
 60	     */
 61	    public void incrementCount(Class<?> animalClass) {
 62	        Counter count = counters.get(animalClass);
 63	        if(count == null) {
 64	            // We do not have a counter for this species yet.
 65	            // Create one.
 66	            count = new Counter(animalClass.getName());
 67	            counters.put(animalClass, count);
 68	        }
 69	        count.increment();
 70	    }
 71	
 72	    /**
 73	     * Indicate that an animal count has been completed.
 74	     */
 75	    public void countFinished()
 76	    {
 77	        countsValid = true;
 78	    }
 79	
 80	    /**
 81	     * Determine whether the simulation is still viable.
 82	     * I.e., should it continue to run.
 83	     * @return true If there is more than one species alive.
 84	     */
 85	    public boolean isViable(Field field) {
 86	        // How many counts are non-zero.
 87	        int nonZero = 0;
 88	        if(!countsValid) {
 89	            generateCounts(field);
 90	        }
 91	        for(Counter info : counters.values()) {
 92	            if(info.getCount() > 0) {
 93	                nonZero++;
 94	            }
 95	        }
 96	        return nonZero > 1;
 97	    }
 98	    
 99	    /**
100	     * Generate counts of the number of dingoes and ants.
101	     * These are not kept up to date as dingoes and ants
102	     * are placed in the field, but only when a request
103	     * is made for the information.
104	     * @param field The field to generate the stats for.
105	     */
106	    private void generateCounts(Field field) {
107	        reset();
108	        for(int row = 0; row < field.getDepth(); row++) {
109	            for(int col = 0; col < field.getWidth(); col++) {
110	                Object animal = field.getObjectAt(row, col);
111	                if(animal != null) {
112	                    incrementCount(animal.getClass());
113	                }
114	            }
115	        }
116	        countsValid = true;
117	    }
118	}

